import asyncio
import json
from typing import Any, Callable, Dict, Optional
import httpx
from fastmcp import Server


def create_openapi_mcp_server(spec: Dict[str, Any], client: httpx.AsyncClient) -> Server:
    """Generate an MCP server from an OpenAPI 3.0 specification."""

    server = Server("openapi-mcp")

    for path, path_item in spec.get("paths", {}).items():
        for method, operation in path_item.items():
            if method.lower() not in ["get", "post", "put", "delete", "patch", "head", "options"]:
                continue

            op_id = operation.get("operationId", f"{method}_{path}").replace("-", "_")
            description = operation.get("summary") or operation.get("description") or f"{method.upper()} {path}"
            parameters = operation.get("parameters", [])
            request_body = operation.get("requestBody")

            properties = {}
            required = []

            for param in parameters:
                name = param.get("name")
                schema = param.get("schema", {"type": "string"})
                properties[name] = schema
                if param.get("required"):
                    required.append(name)

            if request_body:
                properties["body"] = {"type": "string", "description": "Request body as JSON string"}
                if request_body.get("required"):
                    required.append("body")

            input_schema = {
                "type": "object",
                "properties": properties,
                "required": required
            }

            async def create_handler(
                api_path: str,
                http_method: str,
                params_list: list,
                has_body: bool,
                http_client: httpx.AsyncClient
            ) -> Callable:
                async def handler(**kwargs: Any) -> str:
                    url = api_path
                    query_params = {}
                    headers = {}
                    body = None

                    for param in params_list:
                        name = param.get("name")
                        location = param.get("in", "query")

                        if name in kwargs:
                            value = kwargs[name]
                            if location == "path":
                                url = url.replace(f"{{{name}}}", str(value))
                            elif location == "query":
                                query_params[name] = value
                            elif location == "header":
                                headers[name] = str(value)

                    if has_body and "body" in kwargs:
                        body_val = kwargs["body"]
                        if isinstance(body_val, str):
                            try:
                                body = json.loads(body_val)
                            except:
                                body = body_val
                        else:
                            body = body_val

                    try:
                        response = await http_client.request(
                            http_method.upper(),
                            url,
                            params=query_params or None,
                            headers=headers or None,
                            json=body if isinstance(body, dict) else None,
                            content=body if isinstance(body, (str, bytes)) and not isinstance(body, dict) else None
                        )

                        try:
                            resp_data = response.json()
                        except:
                            resp_data = response.text

                        return json.dumps({
                            "status": response.status_code,
                            "body": resp_data
                        })
                    except Exception as e:
                        return json.dumps({"error": str(e)})

                return handler

            handler = asyncio.run(create_handler(path, method, parameters, bool(request_body), client))

            @server.call_tool()
            async def tool_wrapper(**kwargs: Any) -> str:
                return await handler(**kwargs)

            tool_wrapper.__name__ = op_id
            tool_wrapper.__doc__ = description

            server._tools[op_id] = {
                "description": description,
                "inputSchema": input_schema,
                "handler": handler
            }

    return server


async def main():
    spec = {
        "openapi": "3.0.0",
        "info": {"title": "Example API", "version": "1.0.0"},
        "paths": {
            "/users/{id}": {
                "get": {
                    "operationId": "getUser",
                    "summary": "Get user by ID",
                    "parameters": [
                        {"name": "id", "in": "path", "required": True, "schema": {"type": "string"}}
                    ]
                }
            }
        }
    }

    async with httpx.AsyncClient(base_url="https://api.example.com") as client:
        server = create_openapi_mcp_server(spec, client)
        async with server:
            await server.wait_for_shutdown()


if __name__ == "__main__":
    asyncio.run(main())

